SELECT

FROM bt_web_app a
WHERE a.status_cd = '00A'
  AND a.web_app_id = #{webAppId}
  AND a.space_id = #{spaceId}

SELECT web_app_id, app_name, open_type, access_url
FROM bt_web_app
WHERE status_cd = '00A'
  AND web_app_id = #{webAppId}
  AND space_id = #{spaceId}

SELECT a.web_app_id, a.app_name, a.created_time, a.updated_time, (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS creatorName, (SELECT w.space_name FROM bt_workspace w WHERE w.space_id = a.space_id) AS spaceName FROM bt_web_app a WHERE a.status_cd = '00A' AND a.space_id = #{query.spaceId}
AND a.app_name LIKE #{query.appName}
ORDER BY a.updated_time DESC

SELECT app_icon
FROM bt_web_app
WHERE status_cd = '00A'
  AND web_app_id = #{webAppId}
  AND space_id = #{spaceId}
